import React from 'react';
import { motion, useScroll, useTransform, useSpring, useVelocity, useAnimationFrame } from 'framer-motion';
import { useRef } from 'react';

interface ParallaxTextProps {
  children: React.ReactNode;
  baseVelocity: number;
}

function ParallaxText({ children, baseVelocity = 100 }: ParallaxTextProps) {
  const baseX = useRef(0);
  const { scrollY } = useScroll();
  const scrollVelocity = useVelocity(scrollY);
  const smoothVelocity = useSpring(scrollVelocity, {
    damping: 50,
    stiffness: 400
  });
  const velocityFactor = useTransform(smoothVelocity, [0, 1000], [0, 5], {
    clamp: false
  });

  const x = useTransform(baseX.current as any, (v) => `${v}%`); // Using any to bypass strict type check on mutable ref value for this specific transform pattern

  const directionFactor = useRef<number>(1);

  useAnimationFrame((t, delta) => {
    let moveBy = directionFactor.current * baseVelocity * (delta / 1000);

    // Apply scroll velocity effect
    if (velocityFactor.get() < 0) {
      directionFactor.current = -1;
    } else if (velocityFactor.get() > 0) {
      directionFactor.current = 1;
    }

    moveBy += directionFactor.current * moveBy * velocityFactor.get();

    baseX.current += moveBy;
  });

  // Reusable text block
  const TextBlock = () => (
    <span className="block mr-16 text-6xl md:text-8xl font-black uppercase tracking-tighter italic text-transparent" style={{ WebkitTextStroke: "1px rgba(255,255,255,0.4)" }}>
      {children}
    </span>
  );

  return (
    <div className="overflow-hidden m-0 whitespace-nowrap flex flex-nowrap py-8 border-y border-neutral-900 bg-black/50 backdrop-blur-sm">
      <motion.div className="flex whitespace-nowrap" style={{ x }}>
        <TextBlock />
        <TextBlock />
        <TextBlock />
        <TextBlock />
      </motion.div>
    </div>
  );
}

