const MagneticButton = () => {
  const ref = useRef<HTMLButtonElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const springConfig = { damping: 15, stiffness: 150, mass: 0.1 };
  const springX = useSpring(x, springConfig);
  const springY = useSpring(y, springConfig);

  const handleMouseMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    const { clientX, clientY } = e;
    const { height, width, left, top } = ref.current!.getBoundingClientRect();
    const middleX = clientX - (left + width / 2);
    const middleY = clientY - (top + height / 2);
    x.set(middleX);
    y.set(middleY);
  };

  const reset = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={reset}
      style={{ x: springX, y: springY }}
      className="relative group w-48 h-48 rounded-full bg-white text-black flex items-center justify-center overflow-hidden"
    >
      <div className="relative z-10 flex flex-col items-center gap-2">
         <span className="font-bold text-xl tracking-tight">CONTACT</span>
         <ArrowUpRight className="group-hover:rotate-45 transition-transform duration-300" />
