interface MagneticButtonProps {
  href?: string;
  label: string;
  copyValue?: string;
  className?: string;
  isExternal?: boolean;
}

const MagneticButton = ({ href, label, copyValue, className = "w-48 h-48", isExternal }: MagneticButtonProps) => {
  const ref = useRef<any>(null);
  const [copied, setCopied] = useState(false);
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const springConfig = { damping: 15, stiffness: 150, mass: 0.1 };
  const springX = useSpring(x, springConfig);
  const springY = useSpring(y, springConfig);

  const handleMouseMove = (e: React.MouseEvent<HTMLElement>) => {
    const { clientX, clientY } = e;
    const { height, width, left, top } = ref.current!.getBoundingClientRect();
    const middleX = clientX - (left + width / 2);
    const middleY = clientY - (top + height / 2);
    x.set(middleX);
    y.set(middleY);
  };

  const reset = () => {
    x.set(0);
    y.set(0);
  };

  const handleClick = (e: React.MouseEvent) => {
    if (copyValue) {
      e.preventDefault();
      navigator.clipboard.writeText(copyValue);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const content = (
    <div className="relative z-10 flex flex-col items-center gap-2 pointer-events-none mix-blend-difference text-black">
       <span className="font-bold tracking-tight">{copied ? "COPIED!" : label}</span>
       {href && !copyValue && <ArrowUpRight className="group-hover:rotate-45 transition-transform duration-300" />}
       {copyValue && (copied ? <Check size={16}/> : <Copy size={16}/>)}
    </div>
  );

  const commonProps = {
    ref,
    onMouseMove: handleMouseMove,
    onMouseLeave: reset,
    style: { x: springX, y: springY },
    className: `relative group rounded-full bg-white flex items-center justify-center overflow-hidden cursor-none ${className}`
  };

  if (href) {
    return (
      <motion.a
        href={href}
        target={isExternal ? "_blank" : undefined}
        rel={isExternal ? "noopener noreferrer" : undefined}
        {...commonProps}
      >
        {content}
        <motion.div 
          className="absolute inset-0 bg-neutral-300 rounded-full scale-0 group-hover:scale-150 transition-transform duration-500 ease-out origin-center -z-0"
        />
      </motion.a>
    );
  }

  return (
    <motion.button
      onClick={handleClick}
      {...commonProps}
    >
      {content}
      <motion.div 
        className="absolute inset-0 bg-neutral-300 rounded-full scale-0 group-hover:scale-150 transition-transform duration-500 ease-out origin-center -z-0"
      />
    </motion.button>
  );
};

