      <h3 className="text-3xl md:text-5xl font-bold mb-6 tracking-tight">{data.title}</h3>
      <p className="text-neutral-400 text-lg md:text-xl font-light leading-relaxed max-w-2xl">
        {data.desc}
      </p>
    </motion.div>
  );
};

