      lenis.raf(time);
      requestAnimationFrame(raf);
    }

    requestAnimationFrame(raf);

    return () => {
      lenis.destroy();
    };
  }, []);

  return (
    <main className="w-full min-h-screen bg-neutral-950 text-white selection:bg-white selection:text-black font-sans">
      <CustomCursor />
      <ScrollProgress />
      <GrainOverlay />

      <Hero />
      <Capability />
      <Projects />
      <Philosophy />
      <Security />
      <Footer />
    </main>
  );
};

